#define KERNEL0 (g_weights + 0)
#define BIAS0   (g_weights + 2688)
#define KERNEL1 (g_weights + 2816)
#define BIAS1   (g_weights + 19200)
#define KERNEL2 (g_weights + 19328)
#define BIAS2   (g_weights + 19840)

static bool weightsValid = true;  // compiled-in checkpoint counts as valid from boot
static bool armed = false;

void policyForward(const float obs[POLICY_OBS_DIM], float actionOut[POLICY_ACTION_DIM])
{
  float h0[128];
  for (int j = 0; j < 128; j++) {
    float acc = BIAS0[j];
    for (int k = 0; k < 21; k++) {
      acc += obs[k] * KERNEL0[k * 128 + j];
    }
    h0[j] = tanhf(acc);
  }
  float h1[128];
  for (int j = 0; j < 128; j++) {
    float acc = BIAS1[j];
    for (int k = 0; k < 128; k++) {
      acc += h0[k] * KERNEL1[k * 128 + j];
    }
    h1[j] = tanhf(acc);
  }
  for (int j = 0; j < 4; j++) {
    float acc = BIAS2[j];
    for (int k = 0; k < 128; k++) {
      acc += h1[k] * KERNEL2[k * 4 + j];
    }
    actionOut[j] = acc;
  }
}

bool policyWeightsValid(void) { return weightsValid; }
void policySetArmed(bool a) { armed = a; }
bool policyIsArmed(void) { return armed; }
uint32_t policyMemSize(void) { return POLICY_HEADER_BYTES + POLICY_TOTAL_BYTES; }

// CRC-32/IEEE (poly 0xEDB88320, reflected, init/final XOR 0xFFFFFFFF) —
// bitwise, no lookup table (a one-shot ~POLICY_TOTAL_BYTES computation per
// upload, never a hot path, so the table's flash/RAM cost isn't worth it).
// Matches Python's zlib.crc32() exactly — see export_policy_c.py's
// export_weights_bin and test_policy_host.c's cross-check against the
// standard "123456789" -> 0xCBF43926 test vector.
static uint32_t policyCrc32(const uint8_t* data, uint32_t len)
{
  uint32_t crc = 0xFFFFFFFFu;
  for (uint32_t i = 0; i < len; i++) {
    crc ^= data[i];
    for (int b = 0; b < 8; b++) {
      uint32_t mask = (uint32_t)(-(int32_t)(crc & 1u));
      crc = (crc >> 1) ^ (0xEDB88320u & mask);
    }
  }
  return crc ^ 0xFFFFFFFFu;
}

typedef struct {
  uint32_t magic;
  uint32_t obsDim;
  uint32_t actionDim;
  uint32_t numLayers;
  uint32_t totalFloats;
  uint32_t crc32;
} PolicyWeightsHeader_t;

static uint8_t headerBuf[POLICY_HEADER_BYTES];
static uint32_t headerBytesWritten = 0;
static bool headerValidated = false;
static uint32_t payloadBytesWritten = 0;

static bool validateHeader(void)
{
  PolicyWeightsHeader_t h;
  memcpy(&h, headerBuf, sizeof(h));
  if (h.magic != POLICY_WEIGHTS_MAGIC) { return false; }
  if (h.obsDim != POLICY_OBS_DIM) { return false; }
  if (h.actionDim != POLICY_ACTION_DIM) { return false; }
  if (h.numLayers != POLICY_NUM_LAYERS) { return false; }
  if (h.totalFloats != POLICY_TOTAL_FLOATS) { return false; }
  return true;
}

bool policyWeightsWrite(uint32_t memAddr, uint32_t writeLen, const uint8_t* data)
{
  // Never mutate g_weights while the control loop might be reading it —
  // see policy.h's policySetArmed() docstring. Also fails closed on a
  // zero-length or out-of-range request.
  if (armed) { return false; }
  const uint32_t memSize = policyMemSize();
  if (writeLen == 0 || memAddr >= memSize || memAddr + writeLen > memSize) { return false; }

  // Assumes strictly sequential, non-overlapping delivery starting at
  // address 0 for each fresh upload — true of cflib's Memory.write() (one
  // write request in flight per memory id, chunks ACKed/sent in order) and
  // simpler than tracking arbitrary out-of-order coverage would be; a
  // resumed/retried upload should always restart from address 0.
  uint32_t addr = memAddr;
  uint32_t remaining = writeLen;
  const uint8_t* src = data;

  if (addr < POLICY_HEADER_BYTES) {
    uint32_t n = remaining;
    if (addr + n > POLICY_HEADER_BYTES) { n = POLICY_HEADER_BYTES - addr; }
    memcpy(headerBuf + addr, src, n);
    if (addr + n > headerBytesWritten) { headerBytesWritten = addr + n; }
    addr += n; src += n; remaining -= n;

    if (headerBytesWritten >= POLICY_HEADER_BYTES && !headerValidated) {
      headerValidated = validateHeader();
      if (!headerValidated) {
        // Reset so the next attempt starts completely fresh — without
        // this, headerBytesWritten would stay >= POLICY_HEADER_BYTES and
        // the very first byte of a subsequent (possibly valid) upload
        // would trigger re-validation against a mix of stale and
        // not-yet-arrived header bytes, before the new header has even
        // fully arrived.
        headerBytesWritten = 0;
        return false;
      }
    }
  }

  if (remaining > 0) {
    if (!headerValidated) { return false; }
    if (payloadBytesWritten == 0) {
      weightsValid = false;  // about to start mutating the live buffer
    }
    uint32_t payloadOffset = addr - POLICY_HEADER_BYTES;
    memcpy((uint8_t*)g_weights + payloadOffset, src, remaining);
    if (payloadOffset + remaining > payloadBytesWritten) {
      payloadBytesWritten = payloadOffset + remaining;
    }

    if (payloadBytesWritten >= POLICY_TOTAL_BYTES) {
      PolicyWeightsHeader_t h;
      memcpy(&h, headerBuf, sizeof(h));
      uint32_t crc = policyCrc32((const uint8_t*)g_weights, POLICY_TOTAL_BYTES);
      weightsValid = (crc == h.crc32);
      // Reset session state so the next upload starts clean regardless of
      // whether this one validated.
      headerBytesWritten = 0;
      headerValidated = false;
      payloadBytesWritten = 0;
    }
  }
  return true;
}
